pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint128 depositAmt, uint128 collectAmt) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0 && collectAmt <= depositAmt);

        // Setup: initialize contract, set MinSum to collect amount for successful collection
        c.SetMinSum(collectAmt);
        c.Initialized();

        // Record initial balance of actor
        uint256 initialBal = c.balances(actor);

        // Deposit
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 afterDepositBal = c.balances(actor);

        // Collect
        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 afterCollectBal = c.balances(actor);

        // Property: final balance = initial balance + deposit - collect
        // This holds for reference C, but fails for mutant M because deposit is not added
        assertEq(afterCollectBal, initialBal + depositAmt - collectAmt);
    }
}

