pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor1, address actor2, uint128 deposit1, uint128 deposit2, uint128 collect1, uint128 collect2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);
        vm.assume(deposit1 > 0 && deposit1 < type(uint128).max / 4);
        vm.assume(deposit2 > 0 && deposit2 < type(uint128).max / 4);
        vm.assume(collect1 <= deposit1);
        vm.assume(collect2 <= deposit2);

        vm.deal(actor1, deposit1);
        vm.deal(actor2, deposit2);

        vm.prank(actor1);
        c.Deposit{value: deposit1}();
        vm.prank(actor2);
        c.Deposit{value: deposit2}();

        vm.warp(block.timestamp + 1);
        vm.prank(actor1);
        c.Collect(uint256(collect1));
        vm.prank(actor2);
        c.Collect(uint256(collect2));

        uint256 totalBal = c.balances(actor1) + c.balances(actor2);
        uint256 totalEth = address(c).balance;
        uint256 totalDeposits = uint256(deposit1) + uint256(deposit2);
        assertTrue(totalBal + totalEth == totalDeposits);
    }
}

