pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, address collector, uint128 depositAmount, uint128 collectAmount, uint128 initialBalance) public {
        vm.assume(depositor != address(0) && collector != address(0) && depositor != collector);
        vm.assume(depositAmount > 0);
        vm.assume(initialBalance == 0);
        vm.assume(collectAmount > 0);

        // Initialize the contract
        c.Initialized();

        // Give the depositor some starting balance
        vm.deal(depositor, type(uint128).max);
        // Give the collector some balance
        vm.deal(collector, type(uint128).max);

        // Make a deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Record the depositor's balance after deposit
        uint256 balanceAfterDeposit = c.balances(depositor);

        // Now make a collect from collector
        vm.prank(collector);
        c.Collect(collectAmount);

        // Read depositor's balance again
        uint256 balanceAfterCollect = c.balances(depositor);

        // Assert: depositor's balance after collect should be >= balance after deposit
        // (it could increase if someone else deposited to them, but in this test it should stay the same)
        assertTrue(balanceAfterCollect >= balanceAfterDeposit);
    }
}

