pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint128 depositAmt, uint128 collectAmt, uint128 otherDeposit) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(depositAmt > 0 && collectAmt > 0 && otherDeposit > 0);
        vm.assume(depositAmt <= type(uint128).max / 2 && otherDeposit <= type(uint128).max / 2);
        vm.assume(collectAmt <= depositAmt);

        // Initialization
        vm.prank(caller);
        c.SetMinSum(0);
        vm.prank(caller);
        c.SetLogFile(address(caller));
        vm.prank(caller);
        c.Initialized();

        // Deposit for caller
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Deposit for other
        vm.deal(other, otherDeposit);
        vm.prank(other);
        c.Deposit{value: otherDeposit}();

        // Caller collects
        vm.prank(caller);
        c.Collect(collectAmt);

        // Assert invariant: contract's Ether balance >= sum of all recorded balances
        uint256 totalBalances = c.balances(caller) + c.balances(other);
        assertTrue(address(c).balance >= totalBalances);
    }
}

