pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address actor, address target) public {
        vm.assume(actor != address(0) && target != address(0));
        vm.assume(amount > 0);
        // Initialize and set up a minimal sum
        c.Initialized();
        c.SetMinSum(0);
        // Fund actor
        vm.deal(actor, amount);
        // Record balances before the operation
        uint256 sumBefore = c.balances(actor) + c.balances(target);
        uint256 ethBefore = address(c).balance;
        // Target makes a deposit to establish a non-zero balance if needed
        if (target != actor) {
            vm.deal(target, 1);
            vm.prank(target);
            c.Deposit{value: 1}();
        }
        // Actor performs a deposit that may revert
        vm.prank(actor);
        try c.Deposit{value: amount}() { } catch { }
        // After the call, compute the total sum of the two balances
        uint256 sumAfter = c.balances(actor) + c.balances(target);
        uint256 ethAfter = address(c).balance;
        // The invariant: total token claim (sum of tracked balances) <= actual ether held
        assertTrue(sumAfter <= ethAfter);
    }
}

